-- Name: fn_actualizar_perfil_usuario(integer, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_actualizar_perfil_usuario(p_id integer, p_nombres character varying, p_apellidos character varying, p_telefono character varying, p_correo character varying, p_contrasena_hash character varying) RETURNS TABLE(id_usuario integer, id_persona integer, correo character varying, rol character varying, id_capilla integer, activo boolean, fecha_registro timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE persona
    SET nombres = p_nombres,
        apellidos = p_apellidos,
        telefono = p_telefono
    WHERE persona.id_persona = (SELECT u.id_persona FROM usuarios u WHERE u.id_usuario = p_id);

    RETURN QUERY
    UPDATE usuarios
    SET correo = p_correo,
        contrasena_hash = COALESCE(p_contrasena_hash, contrasena_hash)
    WHERE usuarios.id_usuario = p_id
    RETURNING usuarios.id_usuario, usuarios.id_persona, usuarios.correo, usuarios.rol, usuarios.id_capilla, usuarios.activo, usuarios.fecha_registro;
END;
$$;


