--
-- TOC entry 355 (class 1255 OID 33224)
-- Name: fn_actualizar_saldo_fondo(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_actualizar_saldo_fondo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE fondos SET saldo_actual = saldo_actual +
      CASE WHEN NEW.tipo = 'Ingreso' THEN NEW.monto ELSE -NEW.monto END
    WHERE id_fondo = NEW.id_fondo;
    RETURN NEW;

  ELSIF TG_OP = 'UPDATE' THEN
    UPDATE fondos SET saldo_actual = saldo_actual -
      CASE WHEN OLD.tipo = 'Ingreso' THEN OLD.monto ELSE -OLD.monto END
    WHERE id_fondo = OLD.id_fondo;
    UPDATE fondos SET saldo_actual = saldo_actual +
      CASE WHEN NEW.tipo = 'Ingreso' THEN NEW.monto ELSE -NEW.monto END
    WHERE id_fondo = NEW.id_fondo;
    RETURN NEW;

  ELSIF TG_OP = 'DELETE' THEN
    UPDATE fondos SET saldo_actual = saldo_actual -
      CASE WHEN OLD.tipo = 'Ingreso' THEN OLD.monto ELSE -OLD.monto END
    WHERE id_fondo = OLD.id_fondo;
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_actualizar_saldo_fondo() OWNER TO postgres;

