--
-- TOC entry 310 (class 1255 OID 33315)
-- Name: fn_crear_evento_misa(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_crear_evento_misa() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_dia_semana TEXT;
BEGIN
    IF NEW.estado = 'Atendida'
       AND NEW.sacramento IN ('Bautizo', 'Matrimonio')
       AND NEW.fecha_asignada IS NOT NULL THEN

        v_dia_semana := CASE EXTRACT(DOW FROM NEW.fecha_asignada)
            WHEN 0 THEN 'Domingo'
            WHEN 1 THEN 'Lunes'
            WHEN 2 THEN 'Martes'
            WHEN 3 THEN 'Miercoles'
            WHEN 4 THEN 'Jueves'
            WHEN 5 THEN 'Viernes'
            WHEN 6 THEN 'Sabado'
        END;

        -- Migra una eucaristÃ­a heredada (creada antes de existir id_solicitud, y por lo
        -- tanto sin vÃ­nculo) que coincida con los valores anteriores de la solicitud:
        -- se le asigna el id_solicitud y se actualiza con los nuevos valores.
        UPDATE eucaristias
           SET id_solicitud = NEW.id_solicitud,
               id_capilla = NEW.id_capilla,
               dia_semana = v_dia_semana,
               fecha = NEW.fecha_asignada,
               hora_inicio = NEW.hora_inicio,
               hora_fin = NEW.hora_fin
         WHERE id_eucaristia = (
             SELECT id_eucaristia
               FROM eucaristias
              WHERE id_solicitud IS NULL
                AND id_capilla = OLD.id_capilla
                AND fecha = OLD.fecha_asignada
                AND hora_inicio = OLD.hora_inicio
              LIMIT 1
         );

        -- Crea la eucaristÃ­a al atender la solicitud, o actualiza la vinculada (mismo
        -- id_solicitud) cuando el Sacerdote modifica fecha/hora de una ya Atendida.
        INSERT INTO eucaristias (
            id_capilla, dia_semana, fecha, hora_inicio, hora_fin, id_sacerdote, estado, id_solicitud
        ) VALUES (
            NEW.id_capilla, v_dia_semana, NEW.fecha_asignada, NEW.hora_inicio,
            NEW.hora_fin, NULL, 'Programada', NEW.id_solicitud
        )
        ON CONFLICT (id_solicitud) DO UPDATE SET
            id_capilla = EXCLUDED.id_capilla,
            dia_semana = EXCLUDED.dia_semana,
            fecha = EXCLUDED.fecha,
            hora_inicio = EXCLUDED.hora_inicio,
            hora_fin = EXCLUDED.hora_fin;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_crear_evento_misa() OWNER TO postgres;

--
