--
-- TOC entry 356 (class 1255 OID 33327)
-- Name: fn_crear_inscrito_al_aprobar(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_crear_inscrito_al_aprobar() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    DECLARE
      v_cedula VARCHAR(10);
      v_nombre_completo VARCHAR(250);
      v_comprobante VARCHAR(500);
    BEGIN
      IF NEW.estado = 'Aprobada' AND OLD.estado IS DISTINCT FROM 'Aprobada' THEN
        SELECT p.cedula, p.nombres || ' ' || p.apellidos, d.archivo_nombre
        INTO v_cedula, v_nombre_completo, v_comprobante
        FROM usuarios u
        JOIN persona p ON p.id_persona = u.id_persona
        LEFT JOIN documentos d ON d.id_documento = NEW.id_documento
        WHERE u.id_usuario = NEW.id_laico;

        INSERT INTO inscritos_catequesis
          (id_inscripcion, cedula, nombres, nivel, id_capilla, fecha_inscripcion, monto, comprobante, estado)
        VALUES
          (NEW.id_inscripcion, v_cedula, v_nombre_completo, NEW.nivel, NEW.id_capilla,
           CURRENT_DATE, NEW.monto, v_comprobante, 'Activo');
      END IF;
      RETURN NEW;
    END;
    $$;


ALTER FUNCTION public.fn_crear_inscrito_al_aprobar() OWNER TO postgres;

