--
-- TOC entry 328 (class 1255 OID 33346)
-- Name: fn_crear_solicitud_con_beneficiarios(integer, character varying, character varying, integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_crear_solicitud_con_beneficiarios(p_id_usuario integer, p_sacramento character varying, p_modalidad character varying, p_id_capilla integer, p_id_documento integer, p_beneficiarios jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_solicitud      solicitudes_sacramento%ROWTYPE;
    v_beneficiario   beneficiarios_solicitud%ROWTYPE;
    v_beneficiarios  JSONB := '[]'::jsonb;
    v_item           JSONB;
BEGIN
    INSERT INTO solicitudes_sacramento (id_usuario, sacramento, modalidad, id_capilla, id_documento)
    VALUES (p_id_usuario, p_sacramento, p_modalidad, p_id_capilla, p_id_documento)
    RETURNING * INTO v_solicitud;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_beneficiarios)
    LOOP
        SELECT * INTO v_beneficiario
        FROM fn_crear_beneficiario_solicitud(
            v_solicitud.id_solicitud,
            v_item->>'rol_beneficiario',
            v_item->>'nombres',
            v_item->>'apellidos',
            v_item->>'cedula',
            v_item->>'telefono',
            (v_item->>'id_persona')::integer
        );

        v_beneficiarios := v_beneficiarios || to_jsonb(v_beneficiario);
    END LOOP;

    RETURN to_jsonb(v_solicitud) || jsonb_build_object('beneficiarios', v_beneficiarios);
END;
$$;


ALTER FUNCTION public.fn_crear_solicitud_con_beneficiarios(p_id_usuario integer, p_sacramento character varying, p_modalidad character varying, p_id_capilla integer, p_id_documento integer, p_beneficiarios jsonb) OWNER TO postgres;

--
-- TOC entry 367 (class 1255 OID 33347)
-- Name: fn_crear_usuario_con_persona(integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_crear_usuario_con_persona(p_id_persona_existente integer, p_cedula character varying, p_nombres character varying, p_apellidos character varying, p_telefono character varying, p_correo character varying, p_contrasena_hash character varying, p_rol character varying, p_id_capilla integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_persona  persona%ROWTYPE;
    v_usuario  RECORD;
BEGIN
    IF p_id_persona_existente IS NOT NULL THEN
        UPDATE persona
        SET nombres = p_nombres,
            apellidos = p_apellidos,
            telefono = p_telefono
        WHERE id_persona = p_id_persona_existente
        RETURNING * INTO v_persona;
    ELSE
        INSERT INTO persona (cedula, nombres, apellidos, telefono)
        VALUES (p_cedula, p_nombres, p_apellidos, p_telefono)
        RETURNING * INTO v_persona;
    END IF;

    INSERT INTO usuarios (id_persona, correo, contrasena_hash, rol, id_capilla)
    VALUES (v_persona.id_persona, p_correo, p_contrasena_hash, p_rol, p_id_capilla)
    RETURNING id_usuario, id_persona, correo, rol, id_capilla, activo, fecha_registro
    INTO v_usuario;

    RETURN to_jsonb(v_usuario) || to_jsonb(v_persona);
END;
$$;


ALTER FUNCTION public.fn_crear_usuario_con_persona(p_id_persona_existente integer, p_cedula character varying, p_nombres character varying, p_apellidos character varying, p_telefono character varying, p_correo character varying, p_contrasena_hash character varying, p_rol character varying, p_id_capilla integer) OWNER TO postgres;

