    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    UPDATE certificados
    SET estado = 'Emitido',
        fecha_emision = p_fecha_emision,
        archivo_url = COALESCE(p_archivo_url, archivo_url),
