--
-- TOC entry 311 (class 1255 OID 33366)
-- Name: fn_fecha_publicacion_comunicado(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fecha_publicacion_comunicado() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.estado = 'Enviado' AND NEW.fecha_publicacion IS NULL
     AND (TG_OP = 'INSERT' OR OLD.estado IS DISTINCT FROM 'Enviado') THEN
    NEW.fecha_publicacion := CURRENT_TIMESTAMP;
  END IF;
  RETURN NEW;
END;
$$;


