-- Name: fn_generar_numero_acta(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_generar_numero_acta() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_anio INT := EXTRACT(YEAR FROM COALESCE(NEW.fecha, CURRENT_DATE));
  v_correlativo INT;
BEGIN
  IF NEW.numero IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(MAX(SUBSTRING(numero FROM 'ACTA-\d{4}-(\d+)')::INT), 0) + 1
  INTO v_correlativo
  FROM actas
  WHERE numero LIKE 'ACTA-' || v_anio || '-%';

  NEW.numero := 'ACTA-' || v_anio || '-' || LPAD(v_correlativo::TEXT, 4, '0');
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_generar_numero_acta() OWNER TO postgres;

--
-- TOC entry 323 (class 1255 OID 33368)
-- Name: fn_guardar_codigo_recuperacion(integer, character varying, timestamp without time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_guardar_codigo_recuperacion(p_id_usuario integer, p_codigo_hash character varying, p_expira timestamp without time zone) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE usuarios
    SET codigo_recuperacion_hash = p_codigo_hash,
        codigo_recuperacion_expira = p_expira
    WHERE id_usuario = p_id_usuario;
END;
$$;


