--
-- TOC entry 330 (class 1255 OID 33369)
-- Name: fn_marcar_eucaristias_pasadas_realizadas(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_marcar_eucaristias_pasadas_realizadas() RETURNS SETOF public.eucaristias
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    UPDATE eucaristias
    SET estado = 'Realizada'
    WHERE estado IN ('Activa', 'Programada')
      AND (
        fecha < CURRENT_DATE
        OR (fecha = CURRENT_DATE AND COALESCE(hora_fin, hora_inicio) < CURRENT_TIME)
      )
    RETURNING *;
END;
$$;


ALTER FUNCTION public.fn_marcar_eucaristias_pasadas_realizadas() OWNER TO postgres;

