--
-- TOC entry 284 (class 1255 OID 33375)
-- Name: fn_registrar_auditoria(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_registrar_auditoria() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_usuario INT;
  v_detalle JSONB;
BEGIN
  BEGIN
    v_usuario := current_setting('app.current_user_id', true)::INT;
  EXCEPTION WHEN OTHERS THEN
    v_usuario := NULL;
  END;

  v_detalle := CASE WHEN TG_OP = 'DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;

  INSERT INTO auditoria (id_usuario, accion, tabla_afectada, detalle)
  VALUES (v_usuario, TG_OP, TG_TABLE_NAME, v_detalle);

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


ALTER FUNCTION public.fn_registrar_auditoria() OWNER TO postgres;

--
-- TOC entry 353 (class 1255 OID 33376)
-- Name: fn_registrar_movimiento_donacion(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_registrar_movimiento_donacion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    DECLARE
      v_id_fondo INT;
      v_usuario_registro INT;
      v_detalle VARCHAR(500);
      v_nombre_fondo VARCHAR(150);
    BEGIN
      IF NEW.estado = 'Aprobado' AND OLD.estado IS DISTINCT FROM 'Aprobado' THEN
        v_id_fondo := NEW.id_fondo;

        IF v_id_fondo IS NULL THEN
          SELECT 'Fondo General - ' || nombre INTO v_nombre_fondo
          FROM capillas
          WHERE id_capilla = NEW.id_capilla;

          v_nombre_fondo := COALESCE(v_nombre_fondo, 'Fondo General - Capilla');

          SELECT id_fondo INTO v_id_fondo
          FROM fondos
          WHERE id_capilla = NEW.id_capilla AND nombre = v_nombre_fondo;

          IF v_id_fondo IS NULL THEN
            INSERT INTO fondos (nombre, descripcion, saldo_actual, id_capilla)
            VALUES (v_nombre_fondo, 'Fondo generado automáticamente', 0, NEW.id_capilla)
            RETURNING id_fondo INTO v_id_fondo;
          END IF;
        END IF;

        v_detalle := COALESCE(
          (SELECT d.archivo_nombre FROM documentos d WHERE d.id_documento = NEW.id_documento),
          'S/N'
        );

        BEGIN
          v_usuario_registro := current_setting('app.current_user_id', true)::INT;
        EXCEPTION WHEN OTHERS THEN
          v_usuario_registro := NULL;
        END;
        v_usuario_registro := COALESCE(v_usuario_registro, NEW.id_usuario);

        INSERT INTO movimientos_financieros
          (tipo, categoria, descripcion, id_fondo, monto, fecha, justificacion, registrado_por)
        VALUES
          ('Ingreso', 'Donación',
           'Donación aprobada - comprobante ' || v_detalle,
           v_id_fondo, NEW.monto, CURRENT_DATE,
           'Generado automáticamente al aprobar donación', v_usuario_registro);
      END IF;
      RETURN NEW;
    END;
    $$;


ALTER FUNCTION public.fn_registrar_movimiento_donacion() OWNER TO postgres;

--
-- TOC entry 295 (class 1255 OID 33377)
-- Name: fn_registrar_movimiento_inscripcion(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_registrar_movimiento_inscripcion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    DECLARE
      v_usuario_registro INT;
      v_id_fondo INT;
      v_nombre_fondo VARCHAR(150);
    BEGIN
      SELECT 'Fondo General - ' || nombre INTO v_nombre_fondo
      FROM capillas
      WHERE id_capilla = NEW.id_capilla;

      v_nombre_fondo := COALESCE(v_nombre_fondo, 'Fondo General - Capilla');

      SELECT id_fondo INTO v_id_fondo
      FROM fondos
      WHERE id_capilla = NEW.id_capilla AND nombre = v_nombre_fondo;

      IF v_id_fondo IS NULL THEN
        INSERT INTO fondos (nombre, descripcion, saldo_actual, id_capilla)
        VALUES (v_nombre_fondo, 'Fondo generado automáticamente', 0, NEW.id_capilla)
        RETURNING id_fondo INTO v_id_fondo;
      END IF;

      BEGIN
        v_usuario_registro := current_setting('app.current_user_id', true)::INT;
      EXCEPTION WHEN OTHERS THEN
        v_usuario_registro := NULL;
      END;

      IF v_usuario_registro IS NULL THEN
        SELECT id_revisor INTO v_usuario_registro
        FROM inscripciones_catequesis
        WHERE id_inscripcion = NEW.id_inscripcion;
      END IF;

      v_usuario_registro := COALESCE(v_usuario_registro, 1);

      INSERT INTO movimientos_financieros
        (tipo, categoria, descripcion, id_fondo, monto, fecha, justificacion, registrado_por)
      VALUES
        ('Ingreso', 'Catequesis',
         'Inscripción catequesis - ' || COALESCE(NEW.nombres, 'S/N'),
         v_id_fondo, COALESCE(NEW.monto, 5.00), CURRENT_DATE,
         'Generado automáticamente al aprobar inscripción', v_usuario_registro);
      RETURN NEW;
    END;
    $$;


ALTER FUNCTION public.fn_registrar_movimiento_inscripcion() OWNER TO postgres;

--
-- TOC entry 288 (class 1255 OID 33378)
-- Name: fn_validar_catequista(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_validar_catequista() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_rol VARCHAR(20);
  v_activo BOOLEAN;
  v_capilla INT;
BEGIN
  IF NEW.id_catequista IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT rol, activo, id_capilla INTO v_rol, v_activo, v_capilla
  FROM usuarios WHERE id_usuario = NEW.id_catequista;

  IF v_rol IS NULL THEN
    RAISE EXCEPTION 'El usuario asignado como catequista no existe';
  END IF;

  IF v_rol NOT IN ('Catequista','Coordinador') THEN
    RAISE EXCEPTION 'El usuario % no tiene rol de Catequista o Coordinador (rol actual: %)', NEW.id_catequista, v_rol;
  END IF;

  IF NOT v_activo THEN
    RAISE EXCEPTION 'El catequista asignado se encuentra inactivo';
  END IF;

  IF v_capilla IS DISTINCT FROM NEW.id_capilla THEN
    RAISE EXCEPTION 'El catequista no pertenece a la capilla de este inscrito';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_validar_catequista() OWNER TO postgres;

--
-- TOC entry 352 (class 1255 OID 33379)
-- Name: fn_validar_solicitud_duplicada(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_validar_solicitud_duplicada() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.modalidad = 'Propia' AND EXISTS (
    SELECT 1 FROM solicitudes_sacramento
    WHERE id_usuario = NEW.id_usuario
      AND sacramento = NEW.sacramento
      AND id_capilla IS NOT DISTINCT FROM NEW.id_capilla
      AND estado = 'Pendiente'
  ) THEN
    RAISE EXCEPTION 'Ya existe una solicitud de % pendiente para este usuario en esta capilla', NEW.sacramento;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_validar_solicitud_duplicada() OWNER TO postgres;

