           FROM public.capillas
          WHERE (capillas.activa = true)) AS capillas,
    ( SELECT count(DISTINCT inscritos_catequesis.cedula) AS count
           FROM public.inscritos_catequesis
          WHERE ((inscritos_catequesis.estado)::text = 'Activo'::text)) AS catequizandos,
    ( SELECT count(*) AS count
           FROM public.usuarios
          WHERE (((usuarios.rol)::text = 'Catequista'::text) AND (usuarios.activo = true))) AS catequistas;


